-- Run this in the Supabase SQL editor once, alongside schema.sql.
-- Stores real accounts (email + bcrypt password hash). The plaintext password is
-- never stored, only a one-way hash of it. Google sign-in users also get a row here.

create table if not exists app_users (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  -- bcrypt hash, generated by pages/api/signup.js — never the plaintext password.
  password_hash text not null,
  created_at timestamptz not null default now()
);
